<?php

namespace App\Http\Requests;

use Illuminate\Foundation\Http\FormRequest;

/** A custom push notification to every subscriber (admin panel and API). */
class PushMessageRequest extends FormRequest
{
    public function authorize(): bool
    {
        return (bool) $this->user()?->is_admin;
    }

    public function rules(): array
    {
        // The comments below are the field descriptions in docs/openapi.json (generated by Scramble).
        return [
            /**
             * Notification title, e.g. "Film baru minggu ini".
             *
             * @example Film baru minggu ini
             */
            'title' => ['required', 'string', 'max:100'],
            /**
             * Text under the title.
             *
             * @example 5 film baru sudah bisa ditonton.
             */
            'body' => ['nullable', 'string', 'max:200'],
            /**
             * Page that opens when the notification is tapped: a path on this site (`/category/drama`) or a full
             * URL on this site. Default `/`.
             *
             * @example /category/drama
             */
            'url' => ['nullable', 'string', 'max:500', function ($attr, $value, $fail) {
                if (! self::sameSite((string) $value)) {
                    $fail('The link must be a page on this site, e.g. /category/drama.');
                }
            }],
        ];
    }

    /** "/path" or a full URL on this site's host. */
    public static function sameSite(string $url): bool
    {
        if ($url === '' || (str_starts_with($url, '/') && ! str_starts_with($url, '//'))) {
            return true;
        }

        return strtolower((string) parse_url($url, PHP_URL_HOST)) === strtolower((string) parse_url(url('/'), PHP_URL_HOST))
            && in_array(parse_url($url, PHP_URL_SCHEME), ['http', 'https'], true);
    }

    /** @return array{kind: string, title: string, body: ?string, url: string} */
    public function message(): array
    {
        $url = (string) ($this->validated('url') ?: '/');
        if (str_starts_with($url, 'http')) {
            $url = (string) (parse_url($url, PHP_URL_PATH) ?: '/').(($q = parse_url($url, PHP_URL_QUERY)) ? '?'.$q : '');
        }

        return ['kind' => 'custom', 'title' => $this->validated('title'), 'body' => $this->validated('body'), 'url' => $url];
    }
}
